"""build.py: makes the generated files of the learnings database from their sources.

Sources: _build/lists.json (the fixed lists and the columns) and base/template/learnings.csv
(the twelve invented rows). Writes, each marked as generated:
  base/flags.md                   the lists with what each label means, for the assistant
  base/template/lists.csv         the lists as a table
  base/template/learnings.xlsx    the template: Learnings, Lists and How to use tabs
  level-2-files/claude-skill/learnings-database/   the skill folder to upload to Claude
Then checks: the CSV header is the column list; every row uses only listed values; the
SKILL.md names every area and lesson type; the rows are invented and say so.
Run: python3 projects/learnings-database/_build/build.py   (needs: openpyxl)
"""
import csv, json, os, shutil, sys
from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill, Alignment
from openpyxl.worksheet.datavalidation import DataValidation

here = os.path.dirname(os.path.abspath(__file__))
root = os.path.dirname(here)
L = json.load(open(os.path.join(here, "lists.json")))
GEN = "GENERATED by _build/build.py from _build/lists.json. Edit that file, not this one."
problems = []

# 1. flags.md
lines = ["<!-- " + GEN + " -->", "", "# The lists: how a learning is filed", "",
         "Each row gets one **kind**, one **area** (the type of learning), one **lesson type** and, if it",
         "belongs to one, a **project** (the topic). Use only these values. A word that fits none is",
         "written `new:<word>` and offered to the person for their Lists tab. If the person's sheet has a",
         "Lists tab, its values win over these.", "", "## Kinds", "", "| Kind | Means |", "| --- | --- |"]
lines += [f"| `{k['value']}` | {k['means']} |" for k in L["kinds"]]
lines += ["", "## Areas: the type of learning", "", "| Area | Holds lessons about | Example (invented) |", "| --- | --- | --- |"]
lines += [f"| `{a['value']}` | {a['means']} | {a['example']} |" for a in L["areas"]]
lines += ["", "## Lesson types: what sort of lesson", "", "| Lesson type | Means |", "| --- | --- |"]
lines += [f"| `{t['value']}` | {t['means']} |" for t in L["lesson_types"]]
lines += ["", "## Close calls", "",
          "- **sales or customers?** Before the customer has paid: `sales`. After: `customers`.",
          "- **decisions or the area the decision was about?** Use `decisions` only when the lesson is about *how* the choice was made. A lesson about suppliers that happens to involve a choice is `operations`.",
          "- **coding or working-with-ai?** Building software or formulas, even with an agent: `coding`. Prompting or checking a chatbot's answer for any other work: `working-with-ai`.",
          "- **instruction or communication?** How a task or prompt was worded: `instruction`. Who was told, when: `communication`.",
          "- **process or check?** A step missing from the work: `process`. A step that only verifies the work: `check`.", ""]
open(os.path.join(root, "base", "flags.md"), "w").write("\n".join(lines))

# 2. lists.csv
with open(os.path.join(root, "base", "template", "lists.csv"), "w", newline="") as f:
    w = csv.writer(f); w.writerow(["list", "value", "means"])
    for k in L["kinds"]: w.writerow(["kind", k["value"], k["means"]])
    for a in L["areas"]: w.writerow(["area", a["value"], a["means"]])
    for t in L["lesson_types"]: w.writerow(["lesson_type", t["value"], t["means"]])
    for p in L["projects"]: w.writerow(["project", p, "An invented example project. Replace with your own"])

# 3. check the rows
rows = list(csv.DictReader(open(os.path.join(root, "base", "template", "learnings.csv"))))
header = open(os.path.join(root, "base", "template", "learnings.csv")).readline().strip().split(",")
if header != L["columns"]: problems.append(f"CSV header {header} is not the column list")
allowed = {"kind": {k["value"] for k in L["kinds"]}, "area": {a["value"] for a in L["areas"]},
           "lesson_type": {t["value"] for t in L["lesson_types"]}, "project": set(L["projects"]) | {""},
           "severity": {"low", "medium", "high"}, "status": {"proposed", "accepted", "merged", "retired"},
           "source": {"chat", "review", "person", "agent", "import"}, "sensitive": {"yes", "no"},
           "confidence": {"high", "medium", "low", ""}}
for r in rows:
    for col, ok in allowed.items():
        if r[col] not in ok: problems.append(f"{r['id']}: {col} = {r[col]!r} is not on the list")
    if not r["rule"].startswith("When "): problems.append(f"{r['id']}: rule should start 'When ...'")
    if len(r["rule"].split()) > 25: problems.append(f"{r['id']}: rule is over 25 words")
    if not r["seen"].isdigit() or int(r["seen"]) < 1: problems.append(f"{r['id']}: seen must be 1 or more")

# 4. the xlsx
wb = Workbook(); ws = wb.active; ws.title = "Learnings"
ws.append(L["columns"])
for r in rows: ws.append([int(r[c]) if c == "seen" else r[c] for c in L["columns"]])
head = PatternFill("solid", fgColor="E8E4F7")
for c in ws[1]: c.font = Font(bold=True); c.fill = head
ws.freeze_panes = "A2"
widths = {"rule": 60, "what_happened": 50, "expected": 40, "why": 40, "tags": 30, "area": 16, "lesson_type": 14, "project": 22}
for i, col in enumerate(L["columns"], 1):
    ws.column_dimensions[ws.cell(1, i).column_letter].width = widths.get(col, 12)
ls = wb.create_sheet("Lists"); ls.append(["list", "value", "means"])
for row in csv.reader(open(os.path.join(root, "base", "template", "lists.csv"))):
    if row[0] != "list": ls.append(row)
for c in ls[1]: c.font = Font(bold=True); c.fill = head
ls.column_dimensions["A"].width = 14; ls.column_dimensions["B"].width = 20; ls.column_dimensions["C"].width = 80
# dropdowns on the Learnings tab, read from the Lists tab
n = ls.max_row
def rng(name):
    idx = [i for i in range(2, n + 1) if ls.cell(i, 1).value == name]
    return f"Lists!$B${idx[0]}:$B${idx[-1]}"
for col, name in [("C", "kind"), ("D", "area"), ("F", "lesson_type")]:
    dv = DataValidation(type="list", formula1=rng(name), allow_blank=True, showErrorMessage=False)
    ws.add_data_validation(dv); dv.add(f"{col}2:{col}2000")
for col, vals in [("L", "low,medium,high"), ("M", "proposed,accepted,merged,retired"), ("P", "yes,no"), ("Q", "high,medium,low")]:
    dv = DataValidation(type="list", formula1=f'"{vals}"', allow_blank=True, showErrorMessage=False)
    ws.add_data_validation(dv); dv.add(f"{col}2:{col}2000")
how = wb.create_sheet("How to use")
for line in [
    ["Learnings database: your log of what went wrong, what had to be redone and what worked better than expected."],
    ["The twelve rows on the Learnings tab are invented examples. Delete them when you add your own."],
    [""],
    ["One row is one lesson. The rule column is the lesson as one instruction: When ..., do ..."],
    ["Only you change the status column: proposed (new), accepted (use it), merged (folded into another row), retired (no longer true)."],
    ["seen counts how many times it happened. It should stop rising once the rule is followed."],
    ["sensitive = yes keeps a row out of anything pasted elsewhere. An empty cell counts as yes."],
    ["Edit the Lists tab to add your own projects, or an area you need. The assistant uses what is there."],
    [""],
    ["To use it: give your assistant the learnings-database SKILL.md and this file, then say 'log that: ...' or 'before I start ...'."],
    [GEN.replace("from _build/lists.json", "from _build/lists.json and base/template/learnings.csv")],
]:
    how.append(line)
how.column_dimensions["A"].width = 120; how["A1"].font = Font(bold=True, size=13)
wb.save(os.path.join(root, "base", "template", "learnings.xlsx"))

# 5. the Claude skill folder (level 2): the SKILL.md and its reference, copied unchanged
skill = os.path.join(root, "base", "SKILL.md")
if os.path.exists(skill):
    text = open(skill).read()
    for a in L["areas"]:
        if f"`{a['value']}`" not in text: problems.append(f"SKILL.md does not name the area {a['value']}")
    for t in L["lesson_types"]:
        if f"`{t['value']}`" not in text: problems.append(f"SKILL.md does not name the lesson type {t['value']}")
    if ",".join(L["columns"]) not in text: problems.append("SKILL.md does not hold the header line")
    if len(text.splitlines()) > 300: problems.append(f"SKILL.md is {len(text.splitlines())} lines; keep it under 300")
    dest = os.path.join(root, "level-2-files", "claude-skill", "learnings-database")
    shutil.rmtree(dest, ignore_errors=True); os.makedirs(os.path.join(dest, "references"))
    shutil.copy(skill, dest); shutil.copy(os.path.join(root, "base", "flags.md"), os.path.join(dest, "references"))
else:
    problems.append("base/SKILL.md is missing")

print(f"built flags.md, lists.csv, learnings.xlsx ({len(rows)} rows)")
if problems:
    print("PROBLEMS:"); [print(" -", p) for p in problems]; sys.exit(1)
print("checks: ok")
